/**
 * Save as file.
 *
 * @param {string[]} uris - URIs of messages to save as file.
 */
function SaveAsFile(uris) {
  // For EML files opened from disk, retain the original filename.
  if (uris.length == 1) {
    const url = Services.io.newURI(uris[0]);
    if (url.schemeIs("file")) {
      const fileName = decodeURIComponent(
        url.QueryInterface(Ci.nsIFileURL).fileName
      );
      MessageSaver.saveAs(window.browsingContext, uris[0], fileName);
      return;
    }
  }

  const filenames = [];

  for (const uri of uris) {
    const msgHdr =
      MailServices.messageServiceFromURI(uri).messageURIToMsgHdr(uri);
    const nameBase = GenerateFilenameFromMsgHdr(msgHdr);
    let name = GenerateValidFilename(nameBase, ".eml");

    let number = 2;
    while (filenames.includes(name)) {
      // should be unlikely
      name = GenerateValidFilename(nameBase + "-" + number, ".eml");
      number++;
    }
    filenames.push(name);
  }

  if (uris.length == 1) {
    MessageSaver.saveAs(window.browsingContext, uris[0], filenames[0]);
  } else {
    MessageSaver.saveMessages(window.browsingContext, uris, filenames);
  }
}

